import type { KkTopic } from "../index";

const kk: KkTopic = {
  title: "Сандар тізбегі",
  explanation: "**Сандар тізбегі** — белгілі бір ретпен, заңдылықпен орналасқан сандар. Сандар тізбегі белгілі бір санның қосылуы, азайтылуы, көбейтілуі, бөлінуі т.с.с. амалдармен жүзеге асады. Келесі санды табу үшін заңдылықты анықтау керек: көрші сандардың қалай өзгеретінін (қаншаға артады немесе кемиді, неше есе өседі) қараңыз, қатарда кезектесіп келетін екі ереже немесе бір-біріне араласқан екі қатар бар-жоғын тексеріңіз.\n\n### Мысал № 1\n\nТөменде берілген сандар белгілі бір заңдылықпен орналасқан. Сұрақ белгісінің орнына сәйкес келетін санды табыңыз.\n\n3, 8, 13, 18, 23, 28, ?\n\n**Шешімі:** сандар белгілі бір заңдылықпен өсіп жатыр: 3+5=8, 8+5=13, 13+5=18, 18+5=23, 23+5=28. Тізбектегі әр келесі сан алдыңғы санға 5-тің қосылуы арқылы шығып жатыр. Олай болса, ?=28+5=33 болады. **Жауабы: 33.**\n\n### Мысал № 2\n\n4, 5, 7, 10, 14, 19, 25, ?\n\n**Шешімі:** тізбек сандар ретімен (1, 2, 3, …) қосылып жатыр: 4+1=5, 5+2=7, 7+3=10, 10+4=14, 14+5=19, 19+6=25. Олай болса, сұрақ белгісінің орнына сәйкес келетін келесі сан 25+7=32 болады. **Жауабы: 32.**\n\n### Мысал № 3\n\n95, 89, 83, 77, 71, 65, 59, ?\n\n**Шешімі:** тізбектегі барлық сандар 6-ға кеміп жатыр. Олай болса, келесі сан 59−6=53 болады. **Жауабы: 53.**\n\n### Мысал № 4\n\n7, 14, 28, 56, 112, 224, 448, ?\n\n**Шешімі:** тізбектегі барлық сандар 2 есе артып жатыр. Олай болса, келесі сан 448·2=896 болады. **Жауабы: 896.**\n\n### Мысал № 5\n\nТөменде берілген сандар белгілі бір заңдылықпен орналасқан. Тізбекке қарап A ÷ B-ны табыңыз.\n\n729, 243, A, 27, 9, B, 1, ?\n\n**Шешімі:** тізбектегі барлық сандар 3 есе кеміп жатыр: 729÷3=243, 243÷3=81=A, 81÷3=27, 27÷3=9, 9÷3=3=B, 3÷3=1. Олай болса, A-ның орнына 81 және B-ның орнына 3 сәйкес келеді. A÷B=81÷3=27 болады. **Жауабы: 27.**\n\n### Мысал № 6\n\nL мен K сандарының айырмасын табыңыз.\n\n4, 11, 18, 25, K, 39, 46, L\n\n**Шешімі:** сандар белгілі бір заңдылықпен өсіп жатыр: 4+7=11, 11+7=18, 18+7=25, 39+7=46. Тізбектегі әр келесі сан алдыңғы санға 7-нің қосылуы арқылы шығып жатыр. Олай болса, K=25+7=32, L=46+7=53. L−K=53−32=21 болады. **Жауабы: 21.**\n\n### Мысал № 7\n\nТөменде берілген сандардың бірі тізбектегі заңдылықты бұзып тұр. Сол санды және оның орнына сәйкес келетін санды табыңыз.\n\n120, 113, 106, 99, 91, 85, 78\n\n**Шешімі:** сандар 7-ге кеміп жатыр: 120−7=113, 113−7=106, 106−7=99, 99−7=92, 92−7=85, 85−7=78. Тізбектегі заңдылықты бұзып тұрған сан — 91, ал оның орнына сәйкес келетін сан — 92. **Жауабы: 91 санын 92-ге ауыстыру керек.**\n\n### Мысал № 8\n\nТөменде кестеде берілген сандар белгілі бір заңдылықпен орналасқан. Кестедегі боялған бөлікке жауаптардың қайсысы сәйкес келеді?\n\n:::figure {\"kind\": \"scene\", \"width\": 9.0, \"height\": 11.0, \"scale\": 26, \"color\": 1, \"items\": [{\"t\": \"rect\", \"x\": 0.0, \"y\": 0.0, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"1\"}, {\"t\": \"rect\", \"x\": 1.2, \"y\": 0.0, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"2\"}, {\"t\": \"rect\", \"x\": 2.4, \"y\": 0.0, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"3\"}, {\"t\": \"rect\", \"x\": 3.5999999999999996, \"y\": 0.0, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"4\"}, {\"t\": \"rect\", \"x\": 0.0, \"y\": 1.2, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"2\"}, {\"t\": \"rect\", \"x\": 1.2, \"y\": 1.2, \"w\": 1.2, \"h\": 1.2, \"fill\": 1}, {\"t\": \"rect\", \"x\": 2.4, \"y\": 1.2, \"w\": 1.2, \"h\": 1.2, \"fill\": 1}, {\"t\": \"rect\", \"x\": 3.5999999999999996, \"y\": 1.2, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"11\"}, {\"t\": \"rect\", \"x\": 0.0, \"y\": 2.4, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"3\"}, {\"t\": \"rect\", \"x\": 1.2, \"y\": 2.4, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"7\"}, {\"t\": \"rect\", \"x\": 2.4, \"y\": 2.4, \"w\": 1.2, \"h\": 1.2, \"fill\": 1}, {\"t\": \"rect\", \"x\": 3.5999999999999996, \"y\": 2.4, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"25\"}, {\"t\": \"rect\", \"x\": 0.0, \"y\": 3.5999999999999996, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"4\"}, {\"t\": \"rect\", \"x\": 1.2, \"y\": 3.5999999999999996, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"11\"}, {\"t\": \"rect\", \"x\": 2.4, \"y\": 3.5999999999999996, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"25\"}, {\"t\": \"rect\", \"x\": 3.5999999999999996, \"y\": 3.5999999999999996, \"w\": 1.2, \"h\": 1.2, \"fill\": null, \"label\": \"50\"}, {\"t\": \"text\", \"x\": 0.55, \"y\": 6.300000000000001, \"s\": \"A)\", \"size\": 14, \"anchor\": \"middle\"}, {\"t\": \"rect\", \"x\": 1.0, \"y\": 5.4, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"4\"}, {\"t\": \"rect\", \"x\": 2.1, \"y\": 5.4, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"7\"}, {\"t\": \"rect\", \"x\": 2.1, \"y\": 6.5, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"14\"}, {\"t\": \"text\", \"x\": 3.55, \"y\": 6.300000000000001, \"s\": \"B)\", \"size\": 14, \"anchor\": \"middle\"}, {\"t\": \"rect\", \"x\": 4.0, \"y\": 5.4, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"3\"}, {\"t\": \"rect\", \"x\": 5.1, \"y\": 5.4, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"7\"}, {\"t\": \"rect\", \"x\": 5.1, \"y\": 6.5, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"14\"}, {\"t\": \"text\", \"x\": 6.55, \"y\": 6.300000000000001, \"s\": \"C)\", \"size\": 14, \"anchor\": \"middle\"}, {\"t\": \"rect\", \"x\": 7.0, \"y\": 5.4, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"4\"}, {\"t\": \"rect\", \"x\": 8.1, \"y\": 5.4, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"6\"}, {\"t\": \"rect\", \"x\": 8.1, \"y\": 6.5, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"13\"}, {\"t\": \"text\", \"x\": 0.55, \"y\": 9.200000000000001, \"s\": \"D)\", \"size\": 14, \"anchor\": \"middle\"}, {\"t\": \"rect\", \"x\": 1.0, \"y\": 8.3, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"4\"}, {\"t\": \"rect\", \"x\": 2.1, \"y\": 8.3, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"7\"}, {\"t\": \"rect\", \"x\": 2.1, \"y\": 9.4, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"13\"}, {\"t\": \"text\", \"x\": 3.55, \"y\": 9.200000000000001, \"s\": \"E)\", \"size\": 14, \"anchor\": \"middle\"}, {\"t\": \"rect\", \"x\": 4.0, \"y\": 8.3, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"5\"}, {\"t\": \"rect\", \"x\": 5.1, \"y\": 8.3, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"7\"}, {\"t\": \"rect\", \"x\": 5.1, \"y\": 9.4, \"w\": 1.1, \"h\": 1.1, \"fill\": null, \"label\": \"15\"}]}\n\n**Шешімі:** кестедегі әр сан өзінің сол жағындағы және үстіндегі сандардың қосындысына тең: 2+2=4, 3+4=7, 7+7=14. (Тексеру: 4+7=11, 14+11=25.) Олай болса, боялған ұяшықтарда 4, 7 және 14 тұр. **Жауабы: A.**\n\n### Мысал № 9\n\nБелгісіз санды табыңыз.\n\n:::figure {\"kind\": \"table\", \"rows\": [[\"2\", \"3\", \"5\"], [\"3\", \"5\", \"8\"], [\"5\", \"8\", \"?\"]]}\n\n**Шешімі:** әр жолда сандар біртіндеп көбірек санға артады: бірінші жолда +1, +2; екінші жолда +2, +3; үшінші жолда +3, +4. Олай болса, сұрақ белгісінің орнына сәйкес келетін сан 8+4=12 болады. **Жауабы: 12.**\n\n### Мысал № 10\n\nТізбектегі сандардың алғашқы екі қатарында қолданылған амал соңғы екі қатарда да қолданылса, онда сұрақ белгілерінің орнына сәйкес келетін тізбекті табыңыз.\n\nI) 5, 10, 9, 18, 17, 34\nII) 90, 45, 46, 23, 24, 12\nIII) 4, 12, 10, 30, 28, 84\nIV) ?, ?, ?, ?, ?, ?\n\nA) 84, 82, 80, 78, 76, 74\nB) 84, 28, 30, 10, 12, 4\nC) 84, 252, 249, 747, 744, 2232\nD) 84, 42, 40, 20, 18, 9\nE) 84, 168, 171, 342, 345, 690\n\n**Шешімі:** I қатарда кезекпен 2-ге көбейтіліп, 1 алынады. II қатарда кері амалдар: 2-ге бөлініп, 1 қосылады. III қатарда кезекпен ·3 және −2; олай болса, IV қатарда кері амалдар қолданылады: ÷3 және +2. Бұған B нұсқасы сәйкес келеді: 84÷3=28, 28+2=30, 30÷3=10, 10+2=12, 12÷3=4. **Жауабы: B.**\n",
  tasks: {
    "p:p1-tp1": { question: "Сұрақ белгісінің орнына сәйкес келетін санды табыңыз:\n3, 12, 21, 30, 39, 48, ?", solution: "Әр келесі сан алдыңғысынан 9-ға артық: 48+9=57." },
    "p:p1-tp2": { question: "Сандар белгілі бір заңдылықпен жазылған. Сұрақ белгісінің орнына қандай санды қою керек?\n2, 5, 10, 17, 26, 37, ?", solution: "Әр келесі сан алдыңғы санға 3, 5, 7, 9, … қосу арқылы шығады: 37+13=50. Бұл n²+1 түріндегі сандар: 7²+1=50." },
    "p:p1-tp3": { question: "Заңдылықты анықтап, «?» белгісінің орнындағы санды табыңыз.\n6, 18, 30, 42, 54, 66, ?", solution: "Әр келесі сан алдыңғысынан 12-ге артық: 66+12=78." },
    "p:p1-tp4": { question: "Сұрақ белгісінің орнына сәйкес келетін санды табыңыз:\n3, 12, 48, 192, 768, 3072, ?", solution: "Әр келесі сан алдыңғысынан 4 есе артық: 3072·4=12288." },
    "p:p1-tp5": { question: "Берілген сандар белгілі бір заңдылықпен жазылған. K + L + M өрнегінің мәнін табыңыз.\n63, 80, 97, K, 131, L, M", solution: "Әр келесі сан алдыңғысынан 17-ге артық: K: 97+17=114, L: 131+17=148, M: 148+17=165. K+L+M=114+148+165=427." },
    "p:p1-tp6": { question: "Берілген сандар белгілі бір заңдылықпен жазылған. A + B өрнегінің мәнін табыңыз.\n100, 97, 91, 82, 70, 55, A, B", solution: "Әр келесі сан алдыңғы санға 3, 6, 9, 12, … алу арқылы шығады: A: 55−18=37, B: 37−21=16. A+B=37+16=53." },
    "p:p1-tp7a": { question: "Қатарда заңдылыққа сәйкес келмейтін сан бар. Сол санды табыңыз:\n112, 105, 98, 92, 84, 77", solution: "Әр келесі сан алдыңғысынан 7-ге кем: 112, 105, 98, 91, 84, 77. 92 сәйкес келмейді (91 болуы керек)." },
    "p:p1-tp7b": { question: "Сандардың бірі сандар тізбегіне сәйкес келмейді. Оны қандай санмен ауыстыру керек?\n112, 105, 98, 92, 84, 77", solution: "Әр келесі сан алдыңғысынан 7-ге кем: 112, 105, 98, 91, 84, 77. 92 сәйкес келмейді (91 болуы керек)." },
    "p:p1-tp8": { question: "Кестедегі сандар белгілі бір заңдылықпен орналасқан. Екі бос ұяшықтағы сандарды табыңыз (алдымен ортадағысын, содан кейін сол жақ төменгісін).", solution: "Жолдар бойынша сандар 3-ке артады (1, 4, 7 / 5, 8, 11 / 9, 12, 15), бағандар бойынша — 4-ке артады. Демек, ортада 8, сол жақ төменгі бұрышта 9 тұр." },
    "p:p1-tp9": { question: "Сұрақ белгісінің орнына сәйкес келетін санды табыңыз.\n18, 50, 32\n13, 41, 28\n36, 63, ?", solution: "Әр жолда ортадағы сан бірінші және үшінші сандардың қосындысына тең: 18+32=50, 13+28=41. Демек, 36+?=63, ?=63−36=27." },
    "p:p1-tp10": { question: "Алғашқы екі қатардағы заңдылықтар келесі екі қатарға да қолданылады. IV қатарды табыңыз (алты санды жазыңыз).\nI) 40, 46, 43, 49, 46, 52\nII) 40, 34, 37, 31, 34, 28\nIII) 40, 49, 45, 54, 50, 59\nIV) ?, ?, ?, ?, ?, ?", solution: "I қатарда: +6, −3, +6, …; II қатарда кері амалдар: −6, +3, −6, … III қатарда: +9, −4, +9, …, сондықтан IV қатарда: −9, +4, −9, +4, −9: 40, 31, 35, 26, 30, 21." },
    "p:p1-z1ax": { question: "Қатарда заңдылыққа сәйкес келмейтін сан бар. Сол санды табыңыз:\n9, 14, 19, 25, 29, 34, 39, …, …", solution: "Әр келесі сан алдыңғысынан 5-ке артық: 9, 14, 19, 24, 29, 34, 39. 25 сәйкес келмейді (24 болуы керек). Жалғасы: 44, 49." },
    "p:p1-z1ay": { question: "Заңдылықты табыңыз (қатарда бір сәйкес келмейтін сан бар) және қатарды екі санмен жалғастырыңыз:\n9, 14, 19, 25, 29, 34, 39, …, …", solution: "Әр келесі сан алдыңғысынан 5-ке артық: 9, 14, 19, 24, 29, 34, 39. 25 сәйкес келмейді (24 болуы керек). Жалғасы: 44, 49." },
    "p:p1-z1bx": { question: "Қатарда заңдылыққа сәйкес келмейтін сан бар. Сол санды табыңыз:\n60, 56, 55, 52, 50, 46, 45, 41, 40, …, …", solution: "Кезектесіп −4 және −1 амалдары орындалады: 60, 56, 55, 51, 50, 46, 45, 41, 40. 52 сәйкес келмейді (51 болуы керек). Жалғасы: 36, 35." },
    "p:p1-z1by": { question: "Заңдылықты табыңыз (қатарда бір сәйкес келмейтін сан бар) және қатарды екі санмен жалғастырыңыз:\n60, 56, 55, 52, 50, 46, 45, 41, 40, …, …", solution: "Кезектесіп −4 және −1 амалдары орындалады: 60, 56, 55, 51, 50, 46, 45, 41, 40. 52 сәйкес келмейді (51 болуы керек). Жалғасы: 36, 35." },
    "p:p1-z1cx": { question: "Қатарда заңдылыққа сәйкес келмейтін сан бар. Сол санды табыңыз:\n8, 14, 20, 28, 32, 38, 44, …, …", solution: "Әр келесі сан алдыңғысынан 6-ға артық: 8, 14, 20, 26, 32, 38, 44. 28 сәйкес келмейді (26 болуы керек). Жалғасы: 50, 56." },
    "p:p1-z1cy": { question: "Заңдылықты табыңыз (қатарда бір сәйкес келмейтін сан бар) және қатарды екі санмен жалғастырыңыз:\n8, 14, 20, 28, 32, 38, 44, …, …", solution: "Әр келесі сан алдыңғысынан 6-ға артық: 8, 14, 20, 26, 32, 38, 44. 28 сәйкес келмейді (26 болуы керек). Жалғасы: 50, 56." },
    "p:p1-z1dx": { question: "Қатарда заңдылыққа сәйкес келмейтін сан бар. Сол санды табыңыз:\n10, 15, 13, 18, 16, 21, 20, …, …", solution: "Кезектесіп +5 және −2 амалдары орындалады: 10, 15, 13, 18, 16, 21, 19. 20 сәйкес келмейді (19 болуы керек). Жалғасы: 24, 22." },
    "p:p1-z1dy": { question: "Заңдылықты табыңыз (қатарда бір сәйкес келмейтін сан бар) және қатарды екі санмен жалғастырыңыз:\n10, 15, 13, 18, 16, 21, 20, …, …", solution: "Кезектесіп +5 және −2 амалдары орындалады: 10, 15, 13, 18, 16, 21, 19. 20 сәйкес келмейді (19 болуы керек). Жалғасы: 24, 22." },
    "p:p1-z1ex": { question: "Қатарда заңдылыққа сәйкес келмейтін сан бар. Сол санды табыңыз:\n70, 64, 62, 56, 54, 48, 45, …, …", solution: "Кезектесіп −6 және −2 амалдары орындалады: 70, 64, 62, 56, 54, 48, 46. 45 сәйкес келмейді (46 болуы керек). Жалғасы: 40, 38." },
    "p:p1-z1ey": { question: "Заңдылықты табыңыз (қатарда бір сәйкес келмейтін сан бар) және қатарды екі санмен жалғастырыңыз:\n70, 64, 62, 56, 54, 48, 45, …, …", solution: "Кезектесіп −6 және −2 амалдары орындалады: 70, 64, 62, 56, 54, 48, 46. 45 сәйкес келмейді (46 болуы керек). Жалғасы: 40, 38." },
    "p:p1-z1fx": { question: "Қатарда заңдылыққа сәйкес келмейтін сан бар. Сол санды табыңыз:\n6, 6, 15, 14, 24, 24, 33, …, …", solution: "Әр сан екі реттен жазылған, ал сандар 9-ға артады: 6, 6, 15, 15, 24, 24, 33. 14 сәйкес келмейді (15 болуы керек). Жалғасы: 33, 42." },
    "p:p1-z1fy": { question: "Заңдылықты табыңыз (қатарда бір сәйкес келмейтін сан бар) және қатарды екі санмен жалғастырыңыз:\n6, 6, 15, 14, 24, 24, 33, …, …", solution: "Әр сан екі реттен жазылған, ал сандар 9-ға артады: 6, 6, 15, 15, 24, 24, 33. 14 сәйкес келмейді (15 болуы керек). Жалғасы: 33, 42." },
    "p:p1-z2a": { question: "Сандар тізбегін жалғастырыңыз (жетіспейтін сандарды ретімен жазыңыз):\n2, 4, 8, 14, 22, ?, ?, ?", solution: "Әр келесі сан алдыңғы санға 2, 4, 6, 8, … қосу арқылы шығады: 22+10=32, 32+12=44, 44+14=58." },
    "p:p1-z2b": { question: "Сандар тізбегін жалғастырыңыз (жетіспейтін сандарды ретімен жазыңыз):\n5, 11, 10, 16, 15, 21, ?, ?", solution: "Кезектесіп +6 және −1 амалдары орындалады: 21−1=20, 20+6=26." },
    "p:p1-z2c": { question: "Сандар тізбегін жалғастырыңыз (жетіспейтін сандарды ретімен жазыңыз):\n1, 5, 13, 25, 41, ?, ?, ?", solution: "Әр келесі сан алдыңғы санға 4, 8, 12, 16, … қосу арқылы шығады: 41+20=61, 61+24=85, 85+28=113." },
    "p:p1-z2d": { question: "Сандар тізбегін жалғастырыңыз (жетіспейтін сандарды ретімен жазыңыз):\n4, 7, 14, 17, 24, 27, ?, ?", solution: "Кезектесіп +3 және +7 амалдары орындалады: 27+7=34, 34+3=37." },
    "p:p1-z2e": { question: "Сандар тізбегін жалғастырыңыз (жетіспейтін сандарды ретімен жазыңыз):\n0, 2, 6, 12, 20, 30, 42, ?, ?", solution: "Әр келесі сан алдыңғы санға 2, 4, 6, 8, … қосу арқылы шығады: 42+14=56, 56+16=72." },
    "p:p1-z2f": { question: "Сандар тізбегін жалғастырыңыз (жетіспейтін сандарды ретімен жазыңыз):\n7, 12, 17, 22, ?, 32, ?", solution: "Әр келесі сан алдыңғысынан 5-ке артық: 22+5=27, 32+5=37." },
    "p:p1-z3a": { question: "Тимур: берілген қатардың жалғасы (келесі саны) 33 саны болады дейді. Бұл дұрыс па?\n61, 57, 53, 49, 45, 41, 37, …", options: ["Дұрыс", "Қате"], solution: "Әр келесі сан алдыңғысынан 4-ке кем: 37−4=33. Келесі сан — 33, демек, тұжырым дұрыс." },
    "p:p1-z3b": { question: "Дана: берілген қатардың жалғасы (келесі саны) 52 саны болады дейді. Бұл дұрыс па?\n8, 14, 20, 26, 32, 38, 44, …", options: ["Дұрыс", "Қате"], solution: "Әр келесі сан алдыңғысынан 6-ға артық: 44+6=50. Келесі сан — 50, 52 емес, демек, тұжырым қате." },
    "p:p1-z3c": { question: "Расул: берілген қатардың жалғасы (келесі саны) 39 саны болады дейді. Бұл дұрыс па?\n50, 48, 50, 45, 50, 42, 50, …", options: ["Дұрыс", "Қате"], solution: "Тақ орындардағы сандар өзгермейді (әрқашан 50), жұп орындардағы сандар 3-ке кемиді: 42−3=39. Келесі сан — 39, демек, тұжырым дұрыс." },
    "p:p1-z3d": { question: "Аружан: берілген қатардың жалғасы (келесі саны) 24 саны болады дейді. Бұл дұрыс па?\n6, 10, 11, 15, 16, 20, 21, …", options: ["Дұрыс", "Қате"], solution: "Кезектесіп +4 және +1 амалдары орындалады: 21+4=25. Келесі сан — 25, 24 емес, демек, тұжырым қате." },
    "p:p1-z4-13": { question: "Айгерим 9, 15, 11, 17, 13, 19, 15, 21, 17 қатарын жазды, мұнда сандар кезекпен 6-ға артады және 4-ке кемиді. Осы заңдылық бойынша 13 санынан басталатын қатарды жалғастырыңыз: келесі 8 санды жазыңыз.", solution: "13 санынан бастап: +6, −4, +6, −4, … Нәтижесінде 19, 15, 21, 17, 23, 19, 25, 21." },
    "p:p1-z4-21": { question: "Айгерим 9, 15, 11, 17, 13, 19, 15, 21, 17 қатарын жазды, мұнда сандар кезекпен 6-ға артады және 4-ке кемиді. Осы заңдылық бойынша 21 санынан басталатын қатарды жалғастырыңыз: келесі 8 санды жазыңыз.", solution: "21 санынан бастап: +6, −4, +6, −4, … Нәтижесінде 27, 23, 29, 25, 31, 27, 33, 29." },
    "p:p1-z4-17": { question: "Айгерим 9, 15, 11, 17, 13, 19, 15, 21, 17 қатарын жазды, мұнда сандар кезекпен 6-ға артады және 4-ке кемиді. Осы заңдылық бойынша 17 санынан басталатын қатарды жалғастырыңыз: келесі 8 санды жазыңыз.", solution: "17 санынан бастап: +6, −4, +6, −4, … Нәтижесінде 23, 19, 25, 21, 27, 23, 29, 25." },
    "p:p1-z4-3": { question: "Айгерим 9, 15, 11, 17, 13, 19, 15, 21, 17 қатарын жазды, мұнда сандар кезекпен 6-ға артады және 4-ке кемиді. Осы заңдылық бойынша 3 санынан басталатын қатарды жалғастырыңыз: келесі 8 санды жазыңыз.", solution: "3 санынан бастап: +6, −4, +6, −4, … Нәтижесінде 9, 5, 11, 7, 13, 9, 15, 11." },
    "p:p1-z5a": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n4, 13, 22, 31, ?", solution: "Әр келесі сан алдыңғысынан 9-ға артық: 31+9=40." },
    "p:p1-z5b": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n5, 7, 11, 17, ?", solution: "Әр келесі сан алдыңғы санға 2, 4, 6, 8, … қосу арқылы шығады: 17+8=25." },
    "p:p1-z5c": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n612, 595, 578, 561, ?", solution: "Әр келесі сан алдыңғысынан 17-ге кем: 561−17=544." },
    "p:p1-z5d": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n60, ?, 44, 36, 28", solution: "Әр келесі сан алдыңғысынан 8-ге кем: 60−8=52." },
    "p:p1-z5f": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n100, 97, ?, 79, 55", solution: "Әр келесі сан алдыңғы санға 3, 6, 12, 24, … алу арқылы шығады: 97−6=91." },
    "p:p1-z5g": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n3, 14, 25, 36, 47, ?", solution: "Әр келесі сан алдыңғысынан 11-ге артық: 47+11=58." },
    "p:p1-z5h": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n4, 6, 11, 19, 30, ?", solution: "Әр келесі сан алдыңғы санға 2, 5, 8, 11, … қосу арқылы шығады: 30+14=44." },
    "p:p1-z5i": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n30, 32, 37, 39, 44, 46, ?", solution: "Кезектесіп +2 және +5 амалдары орындалады: 46+5=51." },
    "p:p1-z5j": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n5, 10, 20, 40, 80, 160, ?", solution: "Әр келесі сан алдыңғысынан 2 есе артық: 160·2=320." },
    "p:p1-z5k": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n4, 6, 9, 13, 18, ?, 31", solution: "Әр келесі сан алдыңғы санға 2, 3, 4, 5, … қосу арқылы шығады: 18+6=24." },
    "p:p1-z5l": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n17, 30, 43, 56, 69, ?", solution: "Әр келесі сан алдыңғысынан 13-ке артық: 69+13=82." },
    "p:p1-z5m": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n20, 24, 32, 44, 60, ?", solution: "Әр келесі сан алдыңғы санға 4, 8, 12, 16, … қосу арқылы шығады: 60+20=80." },
    "p:p1-z5n": { question: "Жетіспейтін санды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51.\n10, 11, 14, 19, ?, 35", solution: "Әр келесі сан алдыңғы санға 1, 3, 5, 7, … қосу арқылы шығады: 19+7=26." },
    "p:p1-z5e": { question: "Жетіспейтін сандарды жиыннан таңдап, қатарды толықтырыңыз: 82, 58, 40, 25, 24, 91, 44, 544, 52, 26, 80, 57, 320, 31, 51 (екі жетіспейтін санды ретімен жазыңыз).\n7, 13, 21, ?, 43, ?", solution: "Әр келесі сан алдыңғы санға 6, 8, 10, 12, … қосу арқылы шығады: 21+10=31, 43+14=57." },
    "p:p1-z6a": { question: "Бағандардағы сандар белгілі бір заңдылықпен орналасқан (бағандарда 1, 2, 3, 4, 5 ұяшық бар). Бағандардағы сандардың қосындыларын салыстырып, сұрақ белгісінің орнына сәйкес келетін санды табыңыз.", solution: "Бағандардағы сандардың қосындысы: 2+1+3+1+1=8, 2+3+4+2=11, 5+6+3=14, 8+9=17. Қосынды 3-ке артады, демек, бірінші бағанда 17+3=20." },
    "p:p1-z6b": { question: "Жоғарғы қатарда шаршылар: 31, 28, 25, 22, ?; төменгі қатарда шеңберлер: 1, 3, 7, 13, ?. Әр қатардағы сандар өз заңдылығымен орналасқан. Екі санды да табыңыз (алдымен шаршыдағыны, содан кейін шеңбердегіні).", solution: "Шаршылар: сандар 3-ке кемиді, демек, ?=22−3=19. Шеңберлер: сандар 2, 4, 6, 8 болып артады, демек, келесі қосылатын сан 8: 13+8=21." },
    "p:p1-z6c1": { question: "Фигурадағы сандар заңдылықпен орналасқан (әр жол және әр баған бойымен). Сол жақ тік бағандағы бос ұяшықтағы санды табыңыз.", solution: "8, 16, 24, 32, 40 бағанында сандар 8-ге артады, демек, бос ұяшықта 32 тұр." },
    "p:p1-z6c2": { question: "Фигурадағы сандар заңдылықпен орналасқан. 22, 19, 16, …, … көлденең қатарының екі бос ұяшығындағы сандарды табыңыз (ретімен).", solution: "Сандар 3-ке кемиді: 22, 19, 16, 13, 10." },
    "p:p1-z6c3": { question: "Фигурадағы сандар заңдылықпен орналасқан. Оң жақ тік бағанның жоғарғы бос ұяшығындағы санды табыңыз (37-нің үстінде).", solution: "Бағанда сандар жоғарыдан төмен қарай 7-ге кемиді: 44, 37, 30, 23, 16. Демек, жоғарыда 44 тұр." },
    "p:p1-z6c4": { question: "Фигурадағы сандар заңдылықпен орналасқан. 46, 40, 34, 28, …, …, … төменгі жолының үш бос ұяшығындағы сандарды табыңыз (ретімен).", solution: "Сандар 6-ға кемиді: 46, 40, 34, 28, 22, 16, 10. 16 ұяшығы оң жақ бағанның төменінде тұр (44, 37, 30, 23, 16)." },
    "p:p1-g1a": { question: "Мирас 1-ден 80-ге дейінгі сандарды (әрқайсысын бір реттен) суретте көрсетілгендей төрт ішкі-ішке орналасқан бесбұрышқа орналастырды. Үш сыртқы бесбұрыштың әр қабырғасындағы сандардың қосындысы бірдей, сондай-ақ бесбұрыштардың төбелерін қосатын кез келген сызықтағы сандардың қосындысы да бірдей. Сыртқы бесбұрыштың жоғарғы шеңберіндегі санды табыңыз.", solution: "Сыртқы бесбұрыштың төменгі қабырғасы: 3+52+47+78+7+34+29+4=254. Жоғарғы сол жақ қабырға: 5+55+50+76+10+31+26=253, демек, шеңберде 254−253=1 тұр." },
    "p:p1-g1b": { question: "Мирас 1-ден 80-ге дейінгі сандарды (әрқайсысын бір реттен) суретте көрсетілгендей төрт ішкі-ішке орналасқан бесбұрышқа орналастырды. Үш сыртқы бесбұрыштың әр қабырғасындағы сандардың қосындысы бірдей, сондай-ақ бесбұрыштардың төбелерін қосатын кез келген сызықтағы сандардың қосындысы да бірдей. Сыртқы бесбұрыштың қабырғаларындағы үш бос шеңбердегі сандарды табыңыз.", solution: "Қабырғадағы қосынды 254. Сол жақ қабырға: 4+51+46+6+35+30+5=177, демек, 254−177=77. Төменгі оң жақ қабырға: 2+53+48+8+33+28+3=175, демек, 79. Жоғарғы оң жақ қабырға: 1+54+49+9+32+27+2=174, демек, 80." },
    "p:p1-g1c": { question: "Мирас 1-ден 80-ге дейінгі сандарды (әрқайсысын бір реттен) суретте көрсетілгендей төрт ішкі-ішке орналасқан бесбұрышқа орналастырды. Үш сыртқы бесбұрыштың әр қабырғасындағы сандардың қосындысы бірдей, сондай-ақ бесбұрыштардың төбелерін қосатын кез келген сызықтағы сандардың қосындысы да бірдей. Екінші бесбұрыштың алты бос шеңберіндегі сандарды табыңыз.", solution: "Сыртқы бесбұрыштың төбесінен центрге баратын кез келген «сәуледегі» қосынды 92-ге тең (1+15+16+60). Сол жақ төбе: 5+?+20+56=92, ?=11; оң жақ төменгі төбе: 3+?+18+58=92, ?=13. Екінші бесбұрыштың қабырғасындағы қосынды: 15+36+70+71+45+11=248. Сонда жоғарғы оң жақ қабырға: 15+44+72+?+37+14=248, ?=66; оң жақ: 14+?+73+67+38+13=248, ?=43; сол жақ: 11+40+?+75+41+12=248, ?=69; төменгі: 12+39+?+74+42+13=248, ?=68." },
    "p:p1-g1d": { question: "Мирас 1-ден 80-ге дейінгі сандарды (әрқайсысын бір реттен) суретте көрсетілгендей төрт ішкі-ішке орналасқан бесбұрышқа орналастырды. Үш сыртқы бесбұрыштың әр қабырғасындағы сандардың қосындысы бірдей, сондай-ақ бесбұрыштардың төбелерін қосатын кез келген сызықтағы сандардың қосындысы да бірдей. Үшінші бесбұрыштың бес бос шеңберіндегі сандарды табыңыз.", solution: "Төменгі сол жақ төбеден шығатын сәуле: 4+12+?+57=92, ?=19. Үшінші бесбұрыштың қабырғасындағы қосынды: 19+22+63+18=122. Жоғарғы сол жақ қабырға: 16+?+61+20=122, ?=25; жоғарғы оң жақ: 16+?+24+17=122, ?=65; сол жақ: 20+?+62+19=122, ?=21; оң жақ: 17+?+23+18=122, ?=64." },
    "p:p1-g1e": { question: "Мирас 1-ден 80-ге дейінгі сандарды (әрқайсысын бір реттен) суретте көрсетілгендей төрт ішкі-ішке орналасқан бесбұрышқа орналастырды. Үш сыртқы бесбұрыштың әр қабырғасындағы сандардың қосындысы бірдей, сондай-ақ бесбұрыштардың төбелерін қосатын кез келген сызықтағы сандардың қосындысы да бірдей. Ішкі (төртінші) бесбұрыштың 2–14–17 сызығындағы бос шеңбердегі санды табыңыз.", solution: "2+14+17+?=92, одан ?=59." },
    "p:p1-g2": { question: "Режиссёр Ернар 15 кадрдан тұратын киноленталы белгілі бір заңдылықпен нөмірлеп шықты. Көмекшісі лентаны 6 бөлікке кесіп тастады (суретте бөліктер араласып тұр). Ернарға бастапқы лентаны қалпына келтіруге көмектесіңіз (15 санды ретімен жазыңыз).", solution: "Лента: 2, 7, 5, 10, 8, 13, 11, 16, 14, 19, 17, 22, 20, 25, 23 — кезекпен +5 және −2. Мұны бөліктердің жалғыз ретті орналасуы дәлелдейді: [2, 7, 5], [10, 8], [13, 11, 16], [14, 19], [17, 22, 20], [25, 23]." },
    "p:p1-g4": { question: "Фигураны 5, 6, 8, 9, 10 және 11 сандарымен (әр санды бір реттен) әр жолдағы, әр бағандағы және екі диагональдағы сандардың қосындысы 21-ге тең болатындай етіп толтырыңыз. Ұяшықтардағы сандарды жазыңыз: жоғарғы сол жақ, жоғарғы оң жақ, ортаңғы сол жақ, ортаңғы оң жақ, төменгі сол жақ, төменгі ортаңғы.", solution: "Сиқырлы шаршы: 10 3 8 / 5 7 9 / 6 11 4. Диагональ: ?+7+4=21, демек, жоғарғы сол жақ ұяшықта 10; сонда 10+3+?=21, жоғарғы оң жақта 8; 8+7+?=21, төменгі сол жақта 6; 10+?+6=21, ортаңғы сол жақта 5; 5+7+?=21, ортаңғы оң жақта 9; 6+?+4=21, төменгі ортаңғыда 11. Барлық жол, бағандар мен диагональдар 21 береді." },
    "p:Т1.1": { question: "Сандар белгілі бір заңдылықпен жазылған. Сұрақ белгісінің орнына қандай санды қою керек?\n9, 14, 11, 16, 13, 18, ?", solution: "Кезектесіп +5 және −3 амалдары орындалады: 18−3=15." },
    "p:Т1.2": { question: "Заңдылықты анықтап, «?» белгісінің орнындағы санды табыңыз.\n40, 39, 33, 32, 26, ?", solution: "Кезектесіп −1 және −6 амалдары орындалады: 26−1=25." },
    "p:Т1.3": { question: "Сұрақ белгісінің орнына сәйкес келетін санды табыңыз:\n17, 4, 17, 10, 17, 16, 17, ?", solution: "Тақ орындардағы сандар өзгермейді (әрқашан 17), жұп орындардағы сандар 6-ға артады: 16+6=22." },
    "p:Т1.4": { question: "Сандар белгілі бір заңдылықпен жазылған. Сұрақ белгісінің орнына қандай санды қою керек?\n12, 30, 12, 41, 12, ?", solution: "Тақ орындардағы сандар өзгермейді (әрқашан 12), жұп орындардағы сандар 11-ге артады: 41+11=52." },
    "p:Т1.5": { question: "Заңдылықты анықтап, «?» белгісінің орнындағы санды табыңыз.\n83, 75, 67, 59, 51, ?", solution: "Әр келесі сан алдыңғысынан 8-ге кем: 51−8=43." },
    "p:Т1.6": { question: "Сұрақ белгісінің орнына сәйкес келетін санды табыңыз:\n6, 7, 11, 12, 16, 17, ?", solution: "Кезектесіп +1 және +4 амалдары орындалады: 17+4=21." },
    "p:Т1.7": { question: "Сандар белгілі бір заңдылықпен жазылған. Сұрақ белгісінің орнына қандай санды қою керек?\n5, 15, 11, 33, 29, 87, ?", solution: "Кезектесіп ·3 және −4 амалдары орындалады: 87−4=83." },
    "p:Т1.8": { question: "Заңдылықты анықтап, «?» белгісінің орнындағы санды табыңыз.\n6, 10, 14, 18, 22, ?", solution: "Әр келесі сан алдыңғысынан 4-ке артық: 22+4=26." },
    "p:Т1.9": { question: "Сұрақ белгісінің орнына сәйкес келетін санды табыңыз:\n11, 11, 19, 19, 27, 27, ?", solution: "Әр сан екі реттен жазылған, ал сандар 8-ге артады: 27+8=35." },
    "p:Т1.10": { question: "Сандар белгілі бір заңдылықпен жазылған. Сұрақ белгісінің орнына қандай санды қою керек?\n41, 38, 42, 39, 43, 40, ?", solution: "Кезектесіп −3 және +4 амалдары орындалады: 40+4=44." },
    "p:Т1.11": { question: "Заңдылықты анықтап, «?» белгісінің орнындағы санды табыңыз.\n100, 103, 109, 118, ?", solution: "Әр келесі сан алдыңғы санға 3, 6, 9, 12, … қосу арқылы шығады: 118+12=130." },
    "p:Т1.12": { question: "Сұрақ белгісінің орнына сәйкес келетін санды табыңыз:\n600, 555, 510, 465, ?", solution: "Әр келесі сан алдыңғысынан 45-ке кем: 465−45=420." },
    "p:Т1.13": { question: "Сандар белгілі бір заңдылықпен жазылған. Сұрақ белгісінің орнына қандай санды қою керек?\n20, 100, 26, 90, 32, ?", solution: "Тақ орындардағы сандар 6-ға артады, жұп орындардағы сандар 10-ға кемиді: 90−10=80." },
    "p:Т1.14": { question: "Заңдылықты анықтап, «?» белгісінің орнындағы санды табыңыз.\n3, 5, 8, 13, 22, 39, ?", solution: "Әр сан алдыңғы санды 2-ге көбейтіп, 1, 2, 3, 4, … алғанға тең: 39·2−6=72." },
    "p:Т1.15": { question: "Сұрақ белгісінің орнына сәйкес келетін санды табыңыз:\n2, 10, 50, 250, ?", solution: "Әр келесі сан алдыңғысынан 5 есе артық: 250·5=1250." },
    "p:Т1.16": { question: "Сандар белгілі бір заңдылықпен жазылған. Сұрақ белгісінің орнына қандай санды қою керек?\n9,5; 8,6; 7,7; 6,8; ?", solution: "Әр келесі сан алдыңғысынан 0,9-ға кем: 6,8−0,9=5,9." },
    "p:Т1.17": { question: "Заңдылықты анықтап, «?» белгісінің орнындағы санды табыңыз.\n5, 4, 7, 20, 79, ?", solution: "Әр сан алдыңғы санды қадам нөміріне көбейтіп, одан 1 алғанға тең: 79·5−1=394." },
    "p:Т1.18": { question: "Сұрақ белгісінің орнына сәйкес келетін санды табыңыз:\n200, 195, ?, 165, 125", solution: "Әр келесі сан алдыңғы санға 5, 10, 20, 40, … алу арқылы шығады: 195−10=185." },
    "p:Т1.19": { question: "Сандар белгілі бір заңдылықпен жазылған. Сұрақ белгісінің орнына қандай санды қою керек?\n9,3; 8,8; 8,3; 7,8; ?", solution: "Әр келесі сан алдыңғысынан 0,5-ке кем: 7,8−0,5=7,3." },
    "p:Т1.20": { question: "Заңдылықты анықтап, «?» белгісінің орнындағы санды табыңыз.\n45, 41, 40, 36, 35, ?", solution: "Кезектесіп −4 және −1 амалдары орындалады: 35−4=31." },
    "p:Т2.1": { question: "Сандар белгілі бір заңдылықпен жазылған. Екі жетіспейтін санды табыңыз (ретімен жазыңыз).\n12, 15, 4, 18, 21, 4, 24, ?, ?", solution: "Сандар үштен топтастырылған; топтарда бірінші сандар 6-ға артады, екінші сандар 6-ға артады, үшінші сандар өзгермейді (әрқашан 4): 21+6=27, 4." },
    "p:Т2.2": { question: "Сандар белгілі бір заңдылықпен жазылған. Екі жетіспейтін санды табыңыз (ретімен жазыңыз).\n120, 111, 102, 93, 84, ?, ?", solution: "Әр келесі сан алдыңғысынан 9-ға кем: 84−9=75, 75−9=66." },
    "p:Т2.3": { question: "Сандар белгілі бір заңдылықпен жазылған. Жетіспейтін сандарды табыңыз (ретімен жазыңыз).\n18, 31, 44, ?, 70, ?", solution: "Әр келесі сан алдыңғысынан 13-ке артық: 44+13=57, 70+13=83." },
    "p:Т2.4": { question: "Сандар белгілі бір заңдылықпен жазылған. Екі жетіспейтін санды табыңыз (ретімен жазыңыз).\n100, 89, 78, 67, 56, 45, 34, ?, ?", solution: "Әр келесі сан алдыңғысынан 11-ге кем: 34−11=23, 23−11=12." },
    "p:Т2.5": { question: "Сандар белгілі бір заңдылықпен жазылған. Екі жетіспейтін санды табыңыз (ретімен жазыңыз).\n8, 23, 38, 53, 68, ?, ?", solution: "Әр келесі сан алдыңғысынан 15-ке артық: 68+15=83, 83+15=98." },
    "p:Т2.6": { question: "Сандар белгілі бір заңдылықпен жазылған. Жетіспейтін сандарды табыңыз (ретімен жазыңыз).\n?, ?, 19, 26, 33, 40, 47", solution: "Әр келесі сан алдыңғысынан 7-ге артық: 19−7=12, 12−7=5." },
    "p:Т2.7": { question: "Сандар белгілі бір заңдылықпен жазылған. Екі жетіспейтін санды табыңыз (ретімен жазыңыз).\n2, 3, 5, 9, 17, ?, ?", solution: "Әр келесі сан алдыңғы санға 1, 2, 4, 8, … қосу арқылы шығады: 17+16=33, 33+32=65." },
    "p:Т2.8": { question: "Сандар белгілі бір заңдылықпен жазылған. Екі жетіспейтін санды табыңыз (ретімен жазыңыз).\n20, 17, 60, 14, 11, 60, 8, ?, ?", solution: "Сандар үштен топтастырылған; топтарда бірінші сандар 6-ға кемиді, екінші сандар 6-ға кемиді, үшінші сандар өзгермейді (әрқашан 60): 11−6=5, 60." },
    "p:Т2.9": { question: "Сандар белгілі бір заңдылықпен жазылған. Жетіспейтін сандарды табыңыз (ретімен жазыңыз).\n3, 15, 27, 39, ?, 63, ?", solution: "Әр келесі сан алдыңғысынан 12-ге артық: 39+12=51, 63+12=75." },
    "p:Т2.10": { question: "Сандар белгілі бір заңдылықпен жазылған. Екі жетіспейтін санды табыңыз (ретімен жазыңыз).\n60, 8, 11, 53, 12, 11, 46, ?, ?", solution: "Сандар үштен топтастырылған; топтарда бірінші сандар 7-ге кемиді, екінші сандар 4-ке артады, үшінші сандар өзгермейді (әрқашан 11): 12+4=16, 11." },
    "p:Т2.11": { question: "Сандар белгілі бір заңдылықпен жазылған. Екі жетіспейтін санды табыңыз (ретімен жазыңыз).\n14, 23, 32, 41, 50, 59, 68, ?, ?", solution: "Әр келесі сан алдыңғысынан 9-ға артық: 68+9=77, 77+9=86." },
    "p:Т2.12": { question: "Сандар белгілі бір заңдылықпен жазылған. Жетіспейтін сандарды табыңыз (ретімен жазыңыз).\n70, 64, 58, 52, ?, ?, 34", solution: "Әр келесі сан алдыңғысынан 6-ға кем: 52−6=46, 46−6=40." },
    "p:Т2.13": { question: "Кемімелі сандар тізбегінің бірінші элементі 300-ге тең, ал әр келесі сан алдыңғысынан 24-ке кем. Алғашқы 6 элементтің қосындысын табыңыз.", solution: "Элементтер: 300, 276, 252, 228, 204, 180. Қосынды: 300+276+252+228+204+180=1440." },
    "p:Т2.14": { question: "Берілген қатарлардың элементтері болатын A, B және C сандарының қосындысын табыңыз:\n8, 20, 32, 44, 56, A\nB, 45, 50, 55, 60, C", solution: "Жоғарғы қатарда сандар 12-ге артады: A=56+12=68. Төменгі қатарда сандар 5-ке артады: B=45−5=40, C=60+5=65. A+B+C=68+40+65=173." },
    "p:Т2.15": { question: "Қатарда заңдылыққа сәйкес келмейтін сан бар. Сол санды табыңыз:\n3, 8, 18, 38, 80, 158", solution: "Әр келесі сан алдыңғы санға 5, 10, 20, 40, … қосу арқылы шығады: 3, 8, 18, 38, 78, 158. 80 сәйкес келмейді (78 болуы керек)." },
    "p:Т2.16": { question: "Берілген сандар белгілі бір заңдылықпен жазылған. A + B өрнегінің мәнін табыңыз.\n4, 7, 13, 22, 34, A, B", solution: "Әр келесі сан алдыңғы санға 3, 6, 9, 12, … қосу арқылы шығады: A: 34+15=49, B: 49+18=67. A+B=49+67=116." },
    "p:Т2.19": { question: "Қатарда заңдылыққа сәйкес келмейтін сан бар. Сол санды табыңыз:\n9, 14, 16, 21, 22, 28, 30", solution: "Кезектесіп +5 және +2 амалдары орындалады: 9, 14, 16, 21, 23, 28, 30. 22 сәйкес келмейді (23 болуы керек)." },
    "p:Т2.20": { question: "Сұрақ белгісінің орнына сәйкес келетін санды табыңыз:\n2, 6, 24, 120, ?, 5040", solution: "Сандар 3, 4, 5, 6, 7, … сандарына көбейтіледі: 120·6=720." },
    "p:Т3.6": { question: "Берілген сандар белгілі бір заңдылықпен жазылған (суретте: 1, 3, 9, 27, 81 және боялған екі фигура A мен B). B − A өрнегінің мәнін табыңыз.", solution: "Әр келесі сан алдыңғысынан 3 есе артық: A=81·3=243, B=243·3=729. B−A=729−243=486." },
    "p:Т3.7": { question: "Екі түрлі тізбек берілген. Шеңберлердегі сандар тізбекпен орналасқан: жоғарғы жолмен солдан оңға қарай, содан кейін оң жақ шетімен төмен және төменгі жолмен оңнан солға қарай. Шаршылардағы сандар: алдымен Y (ол бірінші шаршының астына сызылған), одан кейін жоғарғы қатардағы сандар солдан оңға қарай. X + Y қосындысын табыңыз.", solution: "Шеңберлер: 12, 30, 16, 30, X, 30, 24, 30, 28: тақ орындардағы сандар 4-ке артады (12, 16, 20, 24, 28), жұп орындарда әрқашан 30. Демек, X=20. Шаршылар: Y, 7, 12, 19, 28: сандар 5, 7, 9 болып артады (әр рет 2-ге көп), демек, 5-ден бұрын 3 болған, Y=7−3=4. X+Y=20+4=24." },
    "p:Т3.9": { question: "Сұрақ белгілерінің орнына сәйкес келетін сандарды табыңыз (ретімен жазыңыз):\n8, 19, 30, 41, ?, ?, ?", solution: "Әр келесі сан алдыңғысынан 11-ге артық: 41+11=52, 52+11=63, 63+11=74." },
    "p:Т3.10": { question: "Екі түрлі тізбек берілген: үшбұрыштардағы сандар және шаршылардағы сандар (екі фигурада да сандар жолдар бойымен солдан оңға қарай орналасқан). (A + B + C) − d өрнегінің мәнін табыңыз.", solution: "Үшбұрыштар: C, 29, 25, 34, 30, A, 35, 44 — кезекпен +9 және −4: C=29−9=20, A=30+9=39. Шаршылар: 5, 6, B, 17, 28, d, 73 — әр сан алдыңғы екі санның қосындысына тең: B=5+6=11, d=17+28=45. (A+B+C)−d=(39+11+20)−45=25." },
    "p:s1": { question: "Айжан сандар пирамидасын құрастырды: әр сан өзінің астындағы екі санның қосындысына тең. Пирамиданың төбесіндегі санды табыңыз.", solution: "Екінші қатардың ортаңғы саны: 7+3=10. Үшінші қатардың сол жақ саны: 11+10=21. Төбе: 21+18=39." },
    "p:s2": { question: "3×3 сиқырлы шаршыда әр жолдағы, әр бағандағы және екі диагональдағы сандардың қосындысы бірдей. Сұрақ белгісінің орнына сәйкес келетін санды табыңыз.", solution: "Диагональдағы қосынды: 5+6+7=18. Демек, екінші диагональда 3+6+?=18, одан ?=18−3−6=9." },
    "p:s3": { question: "Шеңбер бойымен сағат тілімен (жоғарғы саннан бастап) сандар белгілі бір заңдылықпен жазылған. Сұрақ белгілерінің орнына сәйкес келетін сандарды табыңыз (сағат тілі бойынша ретімен).", solution: "Сандар 4-ке артады: 5, 9, 13, 17, 21, 25, 29, 33. Демек, сұрақ белгілерінің орнында 17 және 29 тұр." },
    "t:1.1": { question: "Сұрақ белгісінің орнына қою керек санды табыңыз.\n15, 19, 17, 21, 19, 23, ?", options: ["25", "21", "27", "19", "23"], solution: "Кезектесіп +4 және −2 амалдары орындалады: 23−2=21." },
    "t:1.2": { question: "Қатардағы сандар заңдылықпен орналасқан. «?» орнындағы санды табыңыз.\n50, 47, 42, 39, 34, ?", options: ["26", "34", "30", "29", "31"], solution: "Кезектесіп −3 және −5 амалдары орындалады: 34−3=31." },
    "t:1.3": { question: "Сандар белгілі бір заңдылықпен орналасқан. Сұрақ белгісінің орнына қандай сан сәйкес келеді?\n30, 12, 30, 15, 30, 18, 30, ?", options: ["42", "21", "18", "30", "33"], solution: "Тақ орындардағы сандар өзгермейді (әрқашан 30), жұп орындардағы сандар 3-ке артады: 18+3=21." },
    "t:1.4": { question: "Сұрақ белгісінің орнына қою керек санды табыңыз.\n5, 13, 5, 19, 5, ?", options: ["11", "15", "25", "5", "19"], solution: "Тақ орындардағы сандар өзгермейді (әрқашан 5), жұп орындардағы сандар 6-ға артады: 19+6=25." },
    "t:1.5": { question: "Қатардағы сандар заңдылықпен орналасқан. «?» орнындағы санды табыңыз.\n6, 15, 24, 33, 42, ?", options: ["52", "60", "51", "42", "53"], solution: "Әр келесі сан алдыңғысынан 9-ға артық: 42+9=51." },
    "t:1.6": { question: "Сандар белгілі бір заңдылықпен орналасқан. Сұрақ белгісінің орнына қандай сан сәйкес келеді?\n1, 3, 8, 10, 15, 17, ?", options: ["24", "12", "17", "19", "22"], solution: "Кезектесіп +2 және +5 амалдары орындалады: 17+5=22." },
    "t:1.7": { question: "Сұрақ белгісінің орнына қою керек санды табыңыз.\n18, 36, 31, 62, 57, 114, ?", options: ["109", "107", "171", "114", "166"], solution: "Кезектесіп ·2 және −5 амалдары орындалады: 114−5=109." },
    "t:1.8": { question: "Қатардағы сандар заңдылықпен орналасқан. «?» орнындағы санды табыңыз.\n3, 8, 13, 18, 23, ?", options: ["28", "29", "23", "26", "33"], solution: "Әр келесі сан алдыңғысынан 5-ке артық: 23+5=28." },
    "t:1.9": { question: "Сандар белгілі бір заңдылықпен орналасқан. Сұрақ белгісінің орнына қандай сан сәйкес келеді?\n70, 70, 58, 58, 46, 46, ?", options: ["24", "34", "32", "46", "35"], solution: "Әр сан екі реттен жазылған, ал сандар 12-ге кемиді: 46−12=34." },
    "t:1.10": { question: "Сұрақ белгісінің орнына қою керек санды табыңыз.\n30, 28, 33, 31, 36, 34, ?", options: ["34", "39", "32", "38", "37"], solution: "Кезектесіп −2 және +5 амалдары орындалады: 34+5=39." },
    "t:1.11": { question: "Қатардағы сандар заңдылықпен орналасқан. «?» орнындағы санды табыңыз.\n150, 152, 155, 159, ?", options: ["159", "164", "168", "163", "162"], solution: "Әр келесі сан алдыңғы санға 2, 3, 4, 5, … қосу арқылы шығады: 159+5=164." },
    "t:1.12": { question: "Сандар белгілі бір заңдылықпен орналасқан. Сұрақ белгісінің орнына қандай сан сәйкес келеді?\n108, 135, 162, 189, ?", options: ["216", "243", "214", "217", "189"], solution: "Әр келесі сан алдыңғысынан 27-ге артық: 189+27=216." },
    "t:1.13": { question: "Сұрақ белгісінің орнына қою керек санды табыңыз.\n90, 5, 75, 12, 60, ?", options: ["67", "60", "108", "19", "20"], solution: "Тақ орындардағы сандар 15-ке кемиді, жұп орындардағы сандар 7-ге артады: 12+7=19." },
    "t:1.14": { question: "Қатардағы сандар заңдылықпен орналасқан. «?» орнындағы санды табыңыз.\n1, 3, 8, 19, 42, 89, ?", options: ["89", "184", "136", "112", "231"], solution: "Әр сан алдыңғы санды 2-ге көбейтіп, 1, 2, 3, 4, … қосқанға тең: 89·2+6=184." },
    "t:1.15": { question: "Сандар белгілі бір заңдылықпен орналасқан. Сұрақ белгісінің орнына қандай сан сәйкес келеді?\n3, 12, 48, 192, ?", options: ["228", "192", "768", "336", "912"], solution: "Әр келесі сан алдыңғысынан 4 есе артық: 192·4=768." },
    "t:1.16": { question: "Сұрақ белгісінің орнына қою керек санды табыңыз.\n1,4; 2,1; 2,8; 3,5; ?", options: ["3,2", "6,2", "4,9", "4,2", "3,5"], solution: "Әр келесі сан алдыңғысынан 0,7-ге артық: 3,5+0,7=4,2." },
    "t:1.17": { question: "Қатардағы сандар заңдылықпен орналасқан. «?» орнындағы санды табыңыз.\n2, 3, 8, 27, 112, ?", options: ["650", "131", "112", "197", "565"], solution: "Әр сан алдыңғы санға 1 қосып, қадам нөміріне көбейткенге тең: (112+1)·5=565." },
    "t:1.18": { question: "Сандар белгілі бір заңдылықпен орналасқан. Сұрақ белгісінің орнына қандай сан сәйкес келеді?\n5, 7, ?, 19, 35", options: ["9", "13", "11", "12", "7"], solution: "Әр келесі сан алдыңғы санға 2, 4, 8, 16, … қосу арқылы шығады: 7+4=11." },
    "t:1.19": { question: "Сұрақ белгісінің орнына қою керек санды табыңыз.\n2,1; 2,7; 3,3; 3,9; ?", options: ["3,5", "3,9", "6,5", "4,5", "5,1"], solution: "Әр келесі сан алдыңғысынан 0,6-ға артық: 3,9+0,6=4,5." },
    "t:1.20": { question: "Қатардағы сандар заңдылықпен орналасқан. «?» орнындағы санды табыңыз.\n60, 57, 51, 48, 42, ?", options: ["39", "37", "42", "33", "36"], solution: "Кезектесіп −3 және −6 амалдары орындалады: 42−3=39." },
    "t:2.1": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n40, 33, 9, 35, 28, 9, 30, ?, ?", options: ["24, 9", "23, 11", "23, 9", "51, 72", "23, 10"], solution: "Сандар үштен топтастырылған; топтарда бірінші сандар 5-ке кемиді, екінші сандар 5-ке кемиді, үшінші сандар өзгермейді (әрқашан 9): 28−5=23, 9." },
    "t:2.2": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n5, 13, 21, 29, 37, ?, ?", options: ["46, 56", "45, 53", "46, 53", "45, 55", "45, 54"], solution: "Әр келесі сан алдыңғысынан 8-ге артық: 37+8=45, 45+8=53." },
    "t:2.3": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n300, 275, 250, ?, 200, ?", options: ["225, 176", "175, 125", "226, 175", "225, 175", "225, 200"], solution: "Әр келесі сан алдыңғысынан 25-ке кем: 250−25=225, 200−25=175." },
    "t:2.4": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n7, 19, 31, 43, 55, 67, 79, ?, ?", options: ["91, 105", "91, 104", "92, 103", "91, 103", "93, 103"], solution: "Әр келесі сан алдыңғысынан 12-ге артық: 79+12=91, 91+12=103." },
    "t:2.5": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n4, 21, 38, 55, 72, ?, ?", options: ["89, 108", "89, 105", "89, 106", "90, 106", "89, 107"], solution: "Әр келесі сан алдыңғысынан 17-ге артық: 72+17=89, 89+17=106." },
    "t:2.6": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n?, ?, 60, 52, 44, 36, 28", options: ["77, 68", "76, 69", "78, 68", "76, 68", "76, 67"], solution: "Әр келесі сан алдыңғысынан 8-ге кем: 60+8=68, 68+8=76." },
    "t:2.7": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n4, 7, 13, 25, 49, ?, ?", options: ["98, 193", "73, 97", "193, 289", "97, 193", "97, 194"], solution: "Әр келесі сан алдыңғы санға 3, 6, 12, 24, … қосу арқылы шығады: 49+48=97, 97+96=193." },
    "t:2.8": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n4, 7, 50, 10, 13, 50, 16, ?, ?", options: ["20, 50", "19, 50", "19, 51", "18, 50", "21, 50"], solution: "Сандар үштен топтастырылған; топтарда бірінші сандар 6-ға артады, екінші сандар 6-ға артады, үшінші сандар өзгермейді (әрқашан 50): 13+6=19, 50." },
    "t:2.9": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n7, 16, 25, 34, ?, 52, ?", options: ["43, 52", "44, 61", "41, 62", "43, 61", "43, 62"], solution: "Әр келесі сан алдыңғысынан 9-ға артық: 34+9=43, 52+9=61." },
    "t:2.10": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n4, 30, 20, 9, 27, 20, 14, ?, ?", options: ["24, 20", "25, 20", "24, 21", "24, 19", "8, 2"], solution: "Сандар үштен топтастырылған; топтарда бірінші сандар 5-ке артады, екінші сандар 3-ке кемиді, үшінші сандар өзгермейді (әрқашан 20): 27−3=24, 20." },
    "t:2.11": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n85, 79, 73, 67, 61, 55, 49, ?, ?", options: ["43, 38", "37, 43", "41, 38", "44, 37", "43, 37"], solution: "Әр келесі сан алдыңғысынан 6-ға кем: 49−6=43, 43−6=37." },
    "t:2.12": { question: "Сандар белгілі бір заңдылықпен жазылған. Қатарды екі санмен жалғастырыңыз.\n6, 13, 20, 27, ?, ?, 48", options: ["35, 41", "32, 42", "34, 42", "36, 41", "34, 41"], solution: "Әр келесі сан алдыңғысынан 7-ге артық: 27+7=34, 34+7=41." },
    "t:2.13": { question: "Кемімелі сандар тізбегінің бірінші элементі 180-ге тең, ал әр келесі сан алдыңғысынан 17-ге кем. Алғашқы 6 элементтің қосындысын табыңыз.", options: ["842", "1335", "825", "903", "730"], solution: "Элементтер: 180, 163, 146, 129, 112, 95. Қосынды: 180+163+146+129+112+95=825." },
    "t:2.14": { question: "Берілген қатарлардың элементтері болатын A, B және C сандарының қосындысын табыңыз:\n14, 23, 32, 41, 50, A\nB, 60, 54, 48, 42, C", options: ["170", "158", "152", "167", "161"], solution: "Жоғарғы қатарда сандар 9-ға артады: A=50+9=59. Төменгі қатарда сандар 6-ға кемиді: B=60+6=66, C=42−6=36. A+B+C=59+66+36=161." },
    "t:2.15": { question: "Берілген сандар тізбегіне сәйкес келмейтін санды анықтаңыз:\n5, 8, 14, 26, 52, 98", options: ["8", "14", "26", "52", "98"], solution: "Әр келесі сан алдыңғы санға 3, 6, 12, 24, … қосу арқылы шығады: 5, 8, 14, 26, 50, 98. 52 сәйкес келмейді (50 болуы керек)." },
    "t:2.16": { question: "Берілген сандар белгілі бір заңдылықпен жазылған. A + B өрнегінің мәнін табыңыз.\n3, 5, 8, 12, 17, A, B", options: ["57", "55", "52", "49", "53"], solution: "Әр келесі сан алдыңғы санға 2, 3, 4, 5, … қосу арқылы шығады: A: 17+6=23, B: 23+7=30. A+B=23+30=53." },
    "t:2.17": { question: "Қалғандарынан өзгеше заңдылығы бар қатарды анықтаңыз.\nA) 10, 20, 30, 40, 50\nB) 5, 15, 45, 135, 405\nC) 2, 6, 18, 54, 162\nD) 7, 21, 63, 189, 567\nE) 4, 12, 36, 108, 324", options: ["10, 20, 30, 40, 50", "5, 15, 45, 135, 405", "2, 6, 18, 54, 162", "7, 21, 63, 189, 567", "4, 12, 36, 108, 324"], solution: "B, C, D, E қатарларында әр сан 3-ке көбейтіледі, ал A қатарында әр санға 10 қосылады." },
    "t:2.18": { question: "Қай нұсқада 4, 9, 14, 19, 24 қатарының заңдылығы қолданылған?", options: ["3, 8, 13, 18, 23", "7, 12, 11, 16, 15", "6, 11, 17, 24, 32", "5, 10, 20, 40, 80", "8, 12, 16, 20, 24"], solution: "Берілген қатарда әр санға 5 қосылады. A қатары да солай құрылған: 3, 8, 13, 18, 23." },
    "t:2.19": { question: "Берілген сандар тізбегіне сәйкес келмейтін санды анықтаңыз:\n3, 7, 13, 17, 23, 28, 33", options: ["7", "33", "13", "23", "28"], solution: "Кезектесіп +4 және +6 амалдары орындалады: 3, 7, 13, 17, 23, 27, 33. 28 сәйкес келмейді (27 болуы керек)." },
    "t:2.20": { question: "Сұрақ белгісінің орнына сәйкес келетін санды табыңыз:\n1, 2, 6, 24, ?, 720", options: ["28", "120", "42", "24", "138"], solution: "Сандар 2, 3, 4, 5, 6, … сандарына көбейтіледі: 24·5=120." },
    "t:3.1": { question: "Берілген қатарлардағы сандар белгілі бір заңдылықпен орналасқан. Ұқсас заңдылығы бар қатарды табыңыз.\nI) 3, 5, 10, 12, 24, 26\nII) 7, 4, 12, 9, 27, 24\nIII) 100, 96, 24, 20, 5, 1\nIV) ?, ?, ?, ?, ?, ?", options: ["6, 8, 16, 18, 36, 38", "6, 12, 10, 20, 18, 36", "6, 8, 4, 6, 3, 5", "6, 4, 8, 6, 12, 10", "6, 12, 14, 28, 30, 60"], solution: "I қатар: +2 және ·2; II қатар: −3 және ·3; III қатар: −4 және ÷4. «Қосу және көбейту», «алу және көбейту», «алу және бөлу» үйлесімдері кездесті. IV қатарда қалған үйлесім — қосу және бөлу болуы керек. C нұсқасы: 6+2=8, 8÷2=4, 4+2=6, 6÷2=3, 3+2=5." },
    "t:3.2": { question: "Берілген қатарлардағы сандар белгілі бір заңдылықпен орналасқан. Ұқсас заңдылығы бар қатарды табыңыз.\nI) 3, 7, 14, 18, 36, 40\nII) 3, 6, 10, 20, 24, 48\nIII) 4, 1, 5, 2, 10, 7\nIV) ?, ?, ?, ?, ?, ?", options: ["4, 20, 17, 85, 82, 410", "4, 20, 23, 115, 118, 590", "4, 9, 27, 32, 96, 101", "4, 1, 5, 2, 10, 7", "4, 12, 7, 21, 16, 48"], solution: "I қатар: +4 және ·2; II қатар: ·2 және +4 (амалдар реті кері); III қатар: −3 және ·5. Демек, IV қатарда амалдар реті кері: ·5 және −3. A нұсқасы: 4·5=20, 20−3=17, 17·5=85, 85−3=82, 82·5=410." },
    "t:3.3": { question: "Қай нұсқада белгілі бір заңдылыққа сәйкес келмейтін сан бар?", options: ["3, 9, 15, 21, 27, 33", "4, 8, 16, 32, 64, 128", "6, 7, 9, 12, 16, 20", "3, 4, 6, 9, 13, 18", "80, 73, 66, 59, 52, 45"], solution: "Қалған нұсқаларда заңдылықтар бар: +6; ·2; +1, +2, +3, +4, +5; −7. C нұсқасында сандар 1, 2, 3, 4, 5 болып артады: 6, 7, 9, 12, 16, 21 болуы керек, ал 20 тұр." },
    "t:3.4": { question: "Берілген шарттарға сәйкес қатарды анықтаңыз:\n• Келесі сан былай шығады: алдыңғы санды 3-ке көбейтіп, одан 2 алады.\n• Қатардың бірінші элементі 3.", options: ["3, 8, 23, 68, 203", "3, 7, 19, 55, 161", "3, 11, 35, 107, 323", "3, 7, 19, 55, 163", "3, 7, 15, 31, 63"], solution: "3·3−2=7, 7·3−2=19, 19·3−2=55, 55·3−2=163." },
    "t:3.5": { question: "Берілген қатарлардағы сандар белгілі бір заңдылықпен орналасқан. Ұқсас заңдылығы бар қатарды табыңыз.\nI) 1, 3, 9, 11, 33, 35\nII) 71, 69, 23, 21, 7, 5\nIII) 2, 5, 20, 23, 92, 95\nIV) ?, ?, ?, ?, ?, ?", options: ["111, 107, 112, 108, 113, 109", "111, 444, 222, 888, 444, 1776", "111, 108, 27, 24, 6, 3", "111, 333, 328, 984, 979, 2937", "111, 108, 36, 33, 11, 8"], solution: "I қатар: +2 және ·3; II қатар: −2 және ÷3 (кері амалдар); III қатар: +3 және ·4. Демек, IV қатарда кері амалдар орындалады: −3 және ÷4. C нұсқасы: 111−3=108, 108÷4=27, 27−3=24, 24÷4=6, 6−3=3." },
    "t:3.6": { question: "Берілген сандар белгілі бір заңдылықпен жазылған (суретте: 3, 6, 12, 24, 48 және боялған екі фигура A мен B). B − A өрнегінің мәнін табыңыз.", options: ["96", "192", "144", "288", "48"], solution: "Әр келесі сан алдыңғысынан 2 есе артық: A=48·2=96, B=96·2=192. B−A=192−96=96." },
    "t:3.7": { question: "Екі түрлі тізбек берілген. Шеңберлердегі сандар тізбекпен орналасқан: жоғарғы жолмен солдан оңға қарай, содан кейін оң жақ шетімен төмен және төменгі жолмен оңнан солға қарай. Шаршылардағы сандар: алдымен Y (ол бірінші шаршының астына сызылған), одан кейін жоғарғы қатардағы сандар солдан оңға қарай. X + Y қосындысын табыңыз.", options: ["45", "49", "47", "43", "52"], solution: "Шеңберлер: 50, 12, 46, 12, X, 12, 38, 12, 34: тақ орындардағы сандар 4-ке кемиді (50, 46, 42, 38, 34), жұп орындарда әрқашан 12. Демек, X=42. Шаршылар: Y, 8, 13, 20, 29: сандар 5, 7, 9 болып артады (әр рет 2-ге көп), демек, 5-ден бұрын 3 болған, Y=8−3=5. X+Y=42+5=47." },
    "t:3.8": { question: "Қай нұсқада сандар белгілі бір заңдылықсыз орналасқан?", options: ["11, 16, 21, 26, 31", "3, 9, 27, 81, 243", "2, 5, 10, 17, 26", "70, 61, 52, 43, 34", "8, 3, 14, 5, 11"], solution: "Қалған нұсқаларда заңдылықтар бар: +5; ·3; +3, +5, +7, +9; −9. E нұсқасындағы 8, 3, 14, 5, 11 сандары ешқандай қатар құрамайды." },
    "t:3.9": { question: "Сұрақ белгілерінің орнына сәйкес келетін сандарды табыңыз:\n100, 93, 86, 79, ?, ?, ?", options: ["72, 64, 58", "72, 65, 57", "72, 65, 56", "72, 75, 58", "72, 65, 58"], solution: "Әр келесі сан алдыңғысынан 7-ге кем: 79−7=72, 72−7=65, 65−7=58." },
    "t:3.10": { question: "Екі түрлі тізбек берілген: үшбұрыштардағы сандар және шаршылардағы сандар (екі фигурада да сандар жолдар бойымен солдан оңға қарай орналасқан). (A + B + C) − d өрнегінің мәнін табыңыз.", options: ["9", "14", "17", "13", "11"], solution: "Үшбұрыштар: C, 19, 16, 23, 20, A, 24, 31 — кезекпен +7 және −3: C=19−7=12, A=20+7=27. Шаршылар: 3, 5, B, 13, 21, d, 55 — әр сан алдыңғы екі санның қосындысына тең: B=3+5=8, d=13+21=34. (A+B+C)−d=(27+8+12)−34=13." },
    "t:3.11": { question: "Бірінші элементі 1 болатын сандар тізбегі туралы тұжырым берілген: келесі сан былай шығады: алдыңғы санға 3 қосып, нәтижені 2-ге көбейтеді. Қатарды анықтаңыз.", options: ["1, 8, 22, 52, 112", "1, 5, 13, 29, 61", "1, 9, 33, 105, 321", "1, 8, 22, 50, 106", "1, 8, 16, 32, 64"], solution: "(1+3)·2=8, (8+3)·2=22, (22+3)·2=50, (50+3)·2=106." },
    "t:s1": { question: "Тізбектегі сандар белгілі бір заңдылықпен жазылған. Сұрақ белгісінің орнына сәйкес келетін санды табыңыз.", options: ["30", "25", "19", "24", "23"], solution: "Сандар 3, 4, 5, 6, … болып артады: 19+6=25 (одан әрі 25+7=32)." },
  },
};

export default kk;
